/** Real native equipment, survival placement, engine ticks and component custody. Proposed tests, UNRUN. */
public final class ArmorGameTests {
    private static final BlockPos P=new BlockPos(3,3,3);
    private static ItemStack tank(Item item,int air){var stack=new ItemStack(item);stack.set(AllDataComponents.BACKTANK_AIR,air);stack.set(DataComponents.CUSTOM_NAME,Component.literal("Original paid backtank"));var data=new CompoundTag();data.putInt("original_stock_receipt",73);stack.set(DataComponents.CUSTOM_DATA,CustomData.of(data));return stack;}
    private static ItemStack capacityTank(GameTestHelper h){var stack=tank(AllItems.COPPER_BACKTANK,73);stack.enchant(h.getLevel().registryAccess().lookupOrThrow(Registries.ENCHANTMENT).getOrThrow(AllEnchantments.CAPACITY),2);return stack;}
    private static NativeSurvivalTestPlayer place(GameTestHelper h,ItemStack stack){h.setBlock(P.below(),Blocks.STONE);h.setBlock(P.south(2).below(),Blocks.STONE);var session=NativeSurvivalTestPlayer.join(h,Vec3.atCenterOf(h.absolutePos(P.south(2))));var player=session.player();player.setItemInHand(InteractionHand.MAIN_HAND,stack);var support=h.absolutePos(P.below());h.assertTrue(stack.useOn(new UseOnContext(player,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(support).add(0,.5,0),Direction.UP,support,false))).consumesAction()&&stack.isEmpty(),"Actual survival useOn places and debits exactly one original wearable tank");return session;}
    private static BacktankBlockEntity be(GameTestHelper h){return h.getBlockEntity(P,BacktankBlockEntity.class);}
    private static void assertOriginal(GameTestHelper h,ItemStack stack,int air){h.assertTrue(stack.is(AllItems.COPPER_BACKTANK)&&stack.getCount()==1&&stack.getOrDefault(AllDataComponents.BACKTANK_AIR,-1)==air&&stack.getHoverName().getString().equals("Original paid backtank")&&stack.getOrDefault(DataComponents.CUSTOM_DATA,CustomData.EMPTY).copyTag().getIntOr("original_stock_receipt",0)==73&&stack.getEnchantments().entrySet().stream().anyMatch(entry->entry.getKey().is(AllEnchantments.CAPACITY)&&entry.getIntValue()==2),"Original single wearable, current air, actual capacity enchantment, custom name and custom receipt remain intact");}

    @GameTest public void realNativeArmorComponentsAndBlockEntityRegistrations(GameTestHelper h){
        for(var item:List.of(AllItems.COPPER_BACKTANK,AllItems.NETHERITE_BACKTANK,AllItems.COPPER_DIVING_HELMET,AllItems.NETHERITE_DIVING_HELMET,AllItems.COPPER_DIVING_BOOTS,AllItems.NETHERITE_DIVING_BOOTS,AllItems.CARDBOARD_HELMET,AllItems.CARDBOARD_CHESTPLATE,AllItems.CARDBOARD_LEGGINGS,AllItems.CARDBOARD_BOOTS)){var stack=new ItemStack(item);h.assertTrue(stack.getMaxStackSize()==1&&stack.has(DataComponents.EQUIPPABLE)&&stack.has(DataComponents.ATTRIBUTE_MODIFIERS)&&stack.has(DataComponents.ENCHANTABLE)&&stack.has(DataComponents.REPAIRABLE),"All ten original wearables use genuine native equipment/attributes/enchant/repair components");}
        h.assertTrue(!new ItemStack(AllItems.COPPER_BACKTANK).isDamageableItem()&&!new ItemStack(AllItems.NETHERITE_BACKTANK).isDamageableItem()&&new ItemStack(AllItems.COPPER_DIVING_HELMET).getMaxDamage()==ArmorType.HELMET.getDurability(7)&&new ItemStack(AllItems.NETHERITE_DIVING_BOOTS).getMaxDamage()==ArmorType.BOOTS.getDurability(37),"Source undamageable tank and copper/netherite item durability survive the native armor migration");
        h.assertTrue(new ItemStack(AllItems.COPPER_BACKTANK).is(BacktankUtil.PRESSURIZED_AIR_SOURCES)&&new ItemStack(AllItems.NETHERITE_BACKTANK).is(BacktankUtil.PRESSURIZED_AIR_SOURCES)&&AllBlocks.COPPER_BACKTANK.asItem()==AllItems.COPPER_BACKTANK&&AllBlocks.NETHERITE_BACKTANK.asItem()==AllItems.NETHERITE_BACKTANK&&AllItems.COPPER_BACKTANK_PLACEABLE.getActualItem()==AllItems.COPPER_BACKTANK&&AllBlockEntityTypes.simpleType(AllBlocks.COPPER_BACKTANK.defaultBlockState())==AllBlockEntityTypes.BACKTANK&&AllBlockEntityTypes.BACKTANK.isValid(AllBlocks.NETHERITE_BACKTANK.defaultBlockState()),"Separate registered placeable/native BE/real wearable and actual source pressurized-air tags agree");h.succeed();
    }
    @GameTest public void originalCardboardDurabilityFuelAndNativeArmorTags(GameTestHelper h){for(var item:List.of(AllItems.CARDBOARD_HELMET,AllItems.CARDBOARD_CHESTPLATE,AllItems.CARDBOARD_LEGGINGS,AllItems.CARDBOARD_BOOTS)){var stack=new ItemStack(item);h.assertTrue(stack.getMaxDamage()==item.armorType().getDurability(4)&&stack.has(DataComponents.COOKING_FUEL)&&stack.is(ItemTags.TRIMMABLE_ARMOR),"All four source cardboard pieces retain factor4 durability, native context cooking fuel and vanilla trim support");}h.assertTrue(new ItemStack(AllItems.COPPER_DIVING_HELMET).is(ItemTags.HEAD_ARMOR)&&new ItemStack(AllItems.COPPER_BACKTANK).is(ItemTags.CHEST_ARMOR)&&new ItemStack(AllItems.COPPER_DIVING_BOOTS).is(ItemTags.FOOT_ARMOR),"Native armor slot tags apply to real source equipment");h.succeed();}
    @GameTest public void nativeEnchantmentHooksRetainOriginalSourceRestrictions(GameTestHelper h){var enchantments=h.getLevel().registryAccess().lookupOrThrow(Registries.ENCHANTMENT);var stack=capacityTank(h);h.assertTrue(!AllItems.COPPER_BACKTANK.supportsEnchantment(stack,enchantments.getOrThrow(Enchantments.MENDING))&&!AllItems.COPPER_BACKTANK.supportsEnchantment(stack,enchantments.getOrThrow(Enchantments.UNBREAKING))&&AllItems.COPPER_BACKTANK.supportsEnchantment(stack,enchantments.getOrThrow(AllEnchantments.CAPACITY))&&!AllItems.COPPER_DIVING_HELMET.supportsEnchantment(new ItemStack(AllItems.COPPER_DIVING_HELMET),enchantments.getOrThrow(Enchantments.AQUA_AFFINITY)),"Actual native holders keep source capacity support and tank/helmet exclusions");h.succeed();}
    @GameTest public void paidPlacementNativeSaveCloneAndActualPickupPreserveExactOriginalComponents(GameTestHelper h){var original=capacityTank(h);try(var session=place(h,original)){var player=session.player();var tank=be(h);h.assertTrue(tank.getAirLevel()==73&&tank.getCapacityEnchantLevel()==2&&tank.getName().getString().equals("Original paid backtank"),"Real placement transfers exact named enchanted air stock to genuine native BE");var saved=tank.saveWithFullMetadata(h.getLevel().registryAccess());h.assertTrue(saved.getIntOr("Air",-1)==73&&saved.getIntOr("CapacityEnchantment",-1)==2&&saved.contains("Components")&&saved.contains("CustomName")&&saved.contains("Owner"),"Native engine save contains actual source air/capacity/name/component patch and real placer UUID");tank.setAirLevel(41);var block=AllBlocks.COPPER_BACKTANK;assertOriginal(h,block.getCloneItemStack(h.getLevel(),h.absolutePos(P),tank.getBlockState(),true),41);var drops=Block.getDrops(tank.getBlockState(),h.getLevel(),h.absolutePos(P),tank);h.assertTrue(drops.size()==1,"Actual native loot yields one source wearable");assertOriginal(h,drops.getFirst(),41);var pos=h.absolutePos(P);h.assertTrue(tank.getBlockState().useWithoutItem(h.getLevel(),player,new BlockHitResult(Vec3.atCenterOf(pos),Direction.SOUTH,pos,false)).consumesAction()&&h.getBlockState(P).isAir(),"Real native right-click removes the one original block before publishing worn equipment");assertOriginal(h,player.getItemBySlot(EquipmentSlot.CHEST),41);h.assertTrue(player.getMainHandItem().isEmpty()&&h.getLevel().getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,new AABB(pos)).isEmpty(),"Original tank is owned once by real chest slot, with no duplicate held or dropped material");}h.succeed();}
    @GameTest public void nativePickupGuardsPreservePaidTankWhenChestOrBlockHandIsOccupied(GameTestHelper h){try(var session=place(h,capacityTank(h))){var player=session.player();var original=be(h);var pos=h.absolutePos(P);var hit=new BlockHitResult(Vec3.atCenterOf(pos),Direction.SOUTH,pos,false);player.setItemSlot(EquipmentSlot.CHEST,new ItemStack(Items.IRON_CHESTPLATE));h.assertFalse(h.getBlockState(P).useWithoutItem(h.getLevel(),player,hit).consumesAction(),"Occupied native chest cannot consume source block");player.setItemSlot(EquipmentSlot.CHEST,ItemStack.EMPTY);player.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.STONE,3));h.assertFalse(h.getBlockState(P).useWithoutItem(h.getLevel(),player,hit).consumesAction(),"Held real block keeps source building guard");h.assertTrue(be(h)==original&&original.getAirLevel()==73&&player.getMainHandItem().getCount()==3,"Rejected native interactions retain exact paid original block, air and held stock");}h.succeed();}
    @GameTest(maxTicks=120) public void actualEngineTopShaftChargesPausesInWaterAndRetainsTimerWhenStopped(GameTestHelper h){
        h.setBlock(P.below(),Blocks.STONE);for(var side:Direction.Plane.HORIZONTAL)h.setBlock(P.relative(side),Blocks.GLASS);h.setBlock(P,AllBlocks.COPPER_BACKTANK);h.setBlock(P.above(),AllBlocks.CREATIVE_MOTOR.defaultBlockState().setValue(CreativeMotorBlock.FACING,Direction.DOWN));var savedAir=new AtomicInteger();var savedTimer=new AtomicInteger();
        h.runAfterDelay(10,()->{var tank=be(h);h.assertTrue(tank.getSpeed()==-16&&tank.getAirLevel()>0&&tank.getComparatorOutput()>0,"Real downward-facing motor drives source top-only shaft at signed -16 RPM, actual engine recharge and comparator");savedAir.set(tank.getAirLevel());savedTimer.set(tank.airLevelTimer);h.setBlock(P,tank.getBlockState().setValue(BlockStateProperties.WATERLOGGED,true));});
        h.runAfterDelay(30,()->{h.assertTrue(be(h).getAirLevel()==savedAir.get()&&be(h).airLevelTimer==savedTimer.get(),"Actual engine ticks pause both source air and remaining recharge timer while waterlogged");h.setBlock(P,be(h).getBlockState().setValue(BlockStateProperties.WATERLOGGED,false));});
        h.runAfterDelay(65,()->{h.assertTrue(be(h).getAirLevel()>savedAir.get(),"Native drying resumes genuine paid block charging");h.setBlock(P.above(),Blocks.AIR);});
        h.runAfterDelay(75,()->{h.assertTrue(be(h).getSpeed()==0,"Native network removal stops real source tank");savedAir.set(be(h).getAirLevel());savedTimer.set(be(h).airLevelTimer);});
        h.runAfterDelay(100,()->{h.assertTrue(be(h).getAirLevel()==savedAir.get()&&be(h).airLevelTimer==savedTimer.get(),"Stopped native source keeps exact air/timer through real engine ticks");h.succeed();});
    }
    @GameTest(maxTicks=40) public void sideDriveCannotChargeSourceTopOnlyBacktank(GameTestHelper h){h.setBlock(P,AllBlocks.COPPER_BACKTANK);h.setBlock(P.west(),AllBlocks.CREATIVE_MOTOR.defaultBlockState().setValue(CreativeMotorBlock.FACING,Direction.EAST));h.runAfterDelay(25,()->{h.assertTrue(be(h).getSpeed()==0&&be(h).getAirLevel()==0,"Real adjacent horizontal motor cannot drive original upward-only tank shaft");h.succeed();});}
    private static Pig immersed(GameTestHelper h,int x,Block liquid){for(int y=2;y<=5;y++)for(int dx=-1;dx<=1;dx++)for(int dz=-1;dz<=1;dz++)h.setBlock(new BlockPos(x+dx,y,3+dz),liquid);h.setBlock(new BlockPos(x,1,3),Blocks.STONE);var pig=h.spawnWithNoFreeWill(EntityTypes.PIG,x+.5f,3.1f,3.5f);pig.setNoGravity(true);pig.setPermanentlyInvulnerable(true);return pig;}
    private static void copper(LivingEntity entity,int air){entity.setItemSlot(EquipmentSlot.HEAD,new ItemStack(AllItems.COPPER_DIVING_HELMET));entity.setItemSlot(EquipmentSlot.CHEST,tank(AllItems.COPPER_BACKTANK,air));}
    private static void netherite(LivingEntity entity,int air){entity.setItemSlot(EquipmentSlot.HEAD,new ItemStack(AllItems.NETHERITE_DIVING_HELMET));entity.setItemSlot(EquipmentSlot.CHEST,tank(AllItems.NETHERITE_BACKTANK,air));entity.setItemSlot(EquipmentSlot.LEGS,new ItemStack(Items.NETHERITE_LEGGINGS));entity.setItemSlot(EquipmentSlot.FEET,new ItemStack(AllItems.NETHERITE_DIVING_BOOTS));}
    @GameTest(maxTicks=60) public void actualEngineWaterBreathingSpendsOneSecondEveryTwentyTicksAndStopsWhenHelmetRemoved(GameTestHelper h){var pig=immersed(h,3,Blocks.WATER);copper(pig,7);pig.setAirSupply(20);var air=new AtomicInteger();h.runAfterDelay(5,()->{h.assertTrue(pig.isUnderWater()&&pig.getAirSupply()==pig.getMaxAirSupply(),"Genuine mob baseTick enters actual underwater decrease-air boundary and obtains source helmet air");air.set(BacktankUtil.getAir(pig.getItemBySlot(EquipmentSlot.CHEST)));});h.runAfterDelay(25,()->{h.assertTrue(BacktankUtil.getAir(pig.getItemBySlot(EquipmentSlot.CHEST))==air.get()-1&&pig.getAirSupply()==pig.getMaxAirSupply(),"Twenty real native ticks consume exactly one original tank second and retain native max breath");air.set(BacktankUtil.getAir(pig.getItemBySlot(EquipmentSlot.CHEST)));pig.setItemSlot(EquipmentSlot.HEAD,ItemStack.EMPTY);});h.runAfterDelay(45,()->{h.assertTrue(pig.getAirSupply()<pig.getMaxAirSupply()&&BacktankUtil.getAir(pig.getItemBySlot(EquipmentSlot.CHEST))==air.get(),"Actual helmet removal restores native drowning and cannot debit unrelated retained tank air");h.succeed();});}
    @GameTest(maxTicks=50) public void naturalNativeWaterBreathingDoesNotConsumeOriginalAir(GameTestHelper h){var pig=immersed(h,3,Blocks.WATER);copper(pig,9);pig.addEffect(new MobEffectInstance(MobEffects.WATER_BREATHING,200));h.runAfterDelay(40,()->{h.assertTrue(pig.isUnderWater()&&pig.getAirSupply()==pig.getMaxAirSupply()&&BacktankUtil.getAir(pig.getItemBySlot(EquipmentSlot.CHEST))==9,"Native natural breathing guard does not spend the original9 source seconds");h.succeed();});}
    @GameTest(maxTicks=50) public void copperSuitCannotSpendAirOrGrantImmunityInNativeLava(GameTestHelper h){var pig=immersed(h,3,Blocks.LAVA);copper(pig,9);h.runAfterDelay(40,()->{h.assertTrue(pig.isInLava()&&!DivingHelmetItem.canProvideAir(pig,true)&&!pig.fireImmune()&&BacktankUtil.getAir(pig.getItemBySlot(EquipmentSlot.CHEST))==9,"Genuine lava rejects source copper breathing/fire protection without consuming retained copper air");h.succeed();});}
    @GameTest(maxTicks=60) public void realNativeLavaDepletionRemovesDerivedFullNetheriteFireImmunity(GameTestHelper h){var pig=immersed(h,3,Blocks.LAVA);netherite(pig,2);h.runAfterDelay(5,()->h.assertTrue(pig.isInLava()&&pig.fireImmune()&&NetheriteDivingHandler.getDivingBits(pig)==15,"Actual native fireImmune derives the complete real equipped source netherite suit with finite air"));h.runAfterDelay(45,()->{h.assertTrue(BacktankUtil.getAir(pig.getItemBySlot(EquipmentSlot.CHEST))==0&&!pig.fireImmune(),"Real lava baseTicks deplete the original2 seconds and native immunity immediately follows actual empty stock");h.succeed();});}
    @GameTest public void actualNetheriteEquipmentRemovalChangesNativeImmunityWithoutCachedPlayerFlags(GameTestHelper h){var pig=h.spawnWithNoFreeWill(EntityTypes.PIG,3.5f,3,3.5f);netherite(pig,5);h.assertTrue(pig.fireImmune(),"Genuine equipped full source suit protects actual native entity");pig.setItemSlot(EquipmentSlot.LEGS,ItemStack.EMPTY);h.assertFalse(pig.fireImmune(),"Removing one actual native piece immediately invalidates derived immunity");pig.setItemSlot(EquipmentSlot.LEGS,new ItemStack(Items.NETHERITE_LEGGINGS));h.assertTrue(pig.fireImmune(),"Original equipment query recovers full suit without manufacturing cached marker state");pig.getItemBySlot(EquipmentSlot.CHEST).set(AllDataComponents.BACKTANK_AIR,0);h.assertFalse(pig.fireImmune(),"Direct actual component depletion cannot leave stale native immunity");h.succeed();}
    @GameTest(maxTicks=30) public void heavyBootsAffectGenuineEngineWaterMotionAndRespectSwimmingPose(GameTestHelper h){var plain=immersed(h,2,Blocks.WATER);var heavy=immersed(h,5,Blocks.WATER);var swimming=immersed(h,8,Blocks.WATER);heavy.setItemSlot(EquipmentSlot.FEET,new ItemStack(AllItems.COPPER_DIVING_BOOTS));swimming.setItemSlot(EquipmentSlot.FEET,new ItemStack(AllItems.COPPER_DIVING_BOOTS));swimming.setPose(Pose.SWIMMING);h.runAfterDelay(10,()->{h.assertTrue(plain.isInWater()&&heavy.isInWater()&&heavy.getY()<plain.getY()-.1&&Math.abs(swimming.getY()-plain.getY())<.05,"Native LivingEntity ticks accelerate real heavy-boot descent while actual swimming pose keeps vanilla water motion");h.succeed();});}
    private static void cardboard(LivingEntity entity){entity.setItemSlot(EquipmentSlot.HEAD,new ItemStack(AllItems.CARDBOARD_HELMET));entity.setItemSlot(EquipmentSlot.CHEST,new ItemStack(AllItems.CARDBOARD_CHESTPLATE));entity.setItemSlot(EquipmentSlot.LEGS,new ItemStack(AllItems.CARDBOARD_LEGGINGS));entity.setItemSlot(EquipmentSlot.FEET,new ItemStack(AllItems.CARDBOARD_BOOTS));entity.setPose(Pose.CROUCHING);}
    @GameTest public void actualPaidSurvivalPlayerCardboardPoseDimensionsVisibilityAndPieceRemoval(GameTestHelper h){try(var session=NativeSurvivalTestPlayer.join(h,Vec3.atCenterOf(h.absolutePos(P)))){var player=session.player();cardboard(player);player.setShiftKeyDown(true);player.refreshDimensions();h.assertTrue(CardboardArmorHandler.testForStealth(player)&&Math.abs(player.getDimensions(Pose.CROUCHING).height()-.8f)<.001&&Math.abs(player.getDimensions(Pose.CROUCHING).eyeHeight()-.6f)<.001&&player.getVisibilityPercent(h.getLevel(),null)==0,"Actual registered survival player wears source four-piece crouch disguise, native .8/.6 dimensions and zero target visibility");player.setItemSlot(EquipmentSlot.HEAD,ItemStack.EMPTY);h.assertFalse(CardboardArmorHandler.testForStealth(player),"Removing one real native piece breaks source stealth");player.setItemSlot(EquipmentSlot.HEAD,new ItemStack(AllItems.CARDBOARD_HELMET));player.getAbilities().flying=true;h.assertFalse(CardboardArmorHandler.testForStealth(player),"Actual native flight state excludes source cardboard stealth");}h.succeed();}
    @GameTest(maxTicks=35) public void sourceCardboardAlsoClearsActualRetaliationOnNativeNoAiMobs(GameTestHelper h){var pig=h.spawnWithNoFreeWill(EntityTypes.PIG,3.5f,3,3.5f);cardboard(pig);var zombie=h.spawnWithNoFreeWill(EntityTypes.ZOMBIE,5.5f,3,3.5f);zombie.setNoAi(true);h.assertTrue(zombie.isNoAi(),"Literal native NoAI flag is set; removing goals alone does not set this flag");zombie.setTarget(pig);zombie.setLastHurtByMob(pig);h.runAfterDelay(20,()->{h.assertTrue(zombie.isNoAi()&&CardboardArmorHandler.testForStealth(pig)&&zombie.getTarget()==null&&zombie.getLastHurtByMob()==null,"Source pre-tick stealth clears real native target/memory even while ordinary AI is disabled");h.succeed();});}
    @GameTest(maxTicks=35) public void realMobAiTickForgetsActualCardboardRetaliationTarget(GameTestHelper h){var pig=h.spawnWithNoFreeWill(EntityTypes.PIG,3.5f,3,3.5f);pig.setPermanentlyInvulnerable(true);cardboard(pig);var zombie=h.spawn(EntityTypes.ZOMBIE,5.5f,3,3.5f);zombie.setPermanentlyInvulnerable(true);zombie.setTarget(pig);zombie.setLastHurtByMob(pig);h.runAfterDelay(20,()->{h.assertTrue(CardboardArmorHandler.testForStealth(pig)&&zombie.getTarget()==null&&zombie.getLastHurtByMob()==null,"Real serverAiStep clears actual native target and persistent retaliation memory for the genuine four-piece crouching source disguise");h.succeed();});}
}
